\left[
|\mathcal C_k|
-\left\lfloor\log_{\,2^{2^{30}}}
 \det\!\left(I_{|\mathcal C_k|}
       +2^{2^{30}}D_k^{\mathsf T}D_k\right)\right\rfloor
-\left\lfloor\log_{\,2^{2^{30}}}
 \det\!\left(I_{|\mathcal C_{k+1}|}
       +2^{2^{30}}D_{k+1}^{\mathsf T}D_{k+1}\right)\right\rfloor
\right]t^k .
